const std = @import("std");
const mem = std.mem;
const math = std.math;
const Allocator = mem.Allocator;

const Tensor = struct {
    allocator: Allocator,
    data: []f32,
    shape: []usize,
    strides: []usize,
    ndim: usize,

    pub fn init(allocator: Allocator, shape: []const usize) !Tensor {
        const ndim = shape.len;
        var self: Tensor = .{ 
            .allocator = allocator, 
            .shape = try allocator.dupe(usize, shape), 
            .strides = try allocator.alloc(usize, ndim), 
            .data = undefined,
            .ndim = ndim 
        };
        var size: usize = 1;
        var i = ndim;
        while (i > 0) {
            i -= 1;
            self.strides[i] = size;
            size *= shape[i];
        }
        self.data = try allocator.alignedAlloc(f32, 64, size);
        @memset(self.data, 0.0);
        return self;
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
    }

    pub fn copy(self: *const Tensor, allocator: Allocator) !Tensor {
        var new = try init(allocator, self.shape);
        @memcpy(new.data, self.data);
        return new;
    }

    pub fn fill(self: *Tensor, value: f32) void {
        @memset(self.data, value);
    }

    pub fn getIndex(self: *const Tensor, indices: []const usize) usize {
        var idx: usize = 0;
        for (indices, self.strides) |i, s| {
            idx += i * s;
        }
        return idx;
    }

    pub fn get(self: *const Tensor, indices: []const usize) f32 {
        return self.data[self.getIndex(indices)];
    }

    pub fn set(self: *Tensor, indices: []const usize, value: f32) void {
        self.data[self.getIndex(indices)] = value;
    }

    pub fn add(self: *Tensor, other: *const Tensor) !void {
        if (!mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        const len8 = self.data.len / 8;
        var i: usize = 0;
        while (i < len8) : (i += 1) {
            const offset = i * 8;
            const a_slice = self.data[offset..offset + 8];
            const b_slice = other.data[offset..offset + 8];
            inline for (0..8) |j| {
                a_slice[j] += b_slice[j];
            }
        }
        const rem = len8 * 8;
        for (rem..self.data.len) |j| {
            self.data[j] += other.data[j];
        }
    }

    pub fn sub(self: *Tensor, other: *const Tensor) !void {
        if (!mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
