    pub fn addScalar(self: *Tensor, scalar: f32) void {
        const s_vec = @splat(f32, scalar);
        const len8 = self.data.len / 8;
        var i: usize = 0;
        while (i < len8) : (i += 1) {
            const offset = i * 8;
            var a_vec = @as([8]f32, self.data[offset..offset + 8].*);
            a_vec = a_vec + s_vec;
            @memcpy(self.data[offset..offset + 8], &a_vec);
        }
        const rem = len8 * 8;
        for (rem..self.data.len) |j| {
            self.data[j] += scalar;
        }
    }

    pub fn subScalar(self: *Tensor, scalar: f32) void {
        const s_vec = @splat(f32, scalar);
