    }

    pub fn mean(self: *const Tensor, allocator: Allocator, axis: usize) !Tensor {
        if (self.shape[axis] == 0) return error.EmptyAxis;
        var s = try self.sum(allocator, axis);
        defer s.deinit();
        const div = @as(f32, @floatFromInt(self.shape[axis]));
        s.divScalar(div);
        return try s.copy(allocator);
    }

    pub fn variance(self: *const Tensor, allocator: Allocator, axis: usize) !Tensor {
        if (self.shape[axis] <= 1) return error.InvalidForVariance;
        var m = try self.mean(allocator, axis);
        defer m.deinit();
        var diff = try self.copy(allocator);
        defer diff.deinit();
        var b_shape = try allocator.dupe(usize, self.shape);
        defer allocator.free(b_shape);
        b_shape[axis] = 1;
        var b_mean = try m.broadcast(allocator, b_shape);
        defer b_mean.deinit();
        try diff.sub(&b_mean);
        try diff.mul(&diff);
        var v = try diff.sum(allocator, axis);
        defer v.deinit();
        const ddof: f32 = 1.0;
        const n = @as(f32, @floatFromInt(self.shape[axis]));
        v.divScalar(n - ddof);
        return try v.copy(allocator);
    }

    pub fn stddev(self: *const Tensor, allocator: Allocator, axis: usize) !Tensor {
        var v = try self.variance(allocator, axis);
        defer v.deinit();
        v.sqrt();
        return try v.copy(allocator);
    }

    pub fn argmax(self: *const Tensor, allocator: Allocator, axis: usize) !Tensor {
        if (axis >= self.ndim) return error.InvalidAxis;
        if (self.shape[axis] == 0) return error.EmptyAxis;
        var new_shape = try allocator.dupe(usize, self.shape);
        new_shape[axis] = 1;
        var result = try init(allocator, new_shape);
        allocator.free(new_shape);
        var indices = try allocator.alloc(usize, self.ndim);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var max_val = -std.math.inf(f32);
            var max_idx: usize = 0;
            var j: usize = 0;
            while (j < self.shape[axis]) : (j += 1) {
                indices[axis] = j;
                const val = self.get(indices);
                if (val > max_val) {
                    max_val = val;
                    max_idx = j;
                }
            }
            indices[axis] = 0;
            result.set(indices, @as(f32, @floatFromInt(max_idx)));
            var carry = true;
            var k = self.ndim;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    indices[k] += 1;
                    if (indices[k] < self.shape[k]) {
                        carry = false;
                    } else {
                        indices[k] = 0;
                    }
                }
            }
            if (carry) break;
        }
        return result;
    }

