    pub fn max(self: *const Tensor, allocator: Allocator, axis: usize) !Tensor {
        if (axis >= self.ndim) return error.InvalidAxis;
        if (self.shape[axis] == 0) return error.EmptyAxis;
        var new_shape = try allocator.dupe(usize, self.shape);
        new_shape[axis] = 1;
        var result = try init(allocator, new_shape);
        allocator.free(new_shape);
        var indices = try allocator.alloc(usize, self.ndim);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var max_val = -std.math.inf(f32);
            var j: usize = 0;
            while (j < self.shape[axis]) : (j += 1) {
                indices[axis] = j;
                max_val = std.math.max(max_val, self.get(indices));
            }
            indices[axis] = 0;
            result.set(indices, max_val);
            var carry = true;
            var k = self.ndim;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    indices[k] += 1;
                    if (indices[k] < self.shape[k]) {
                        carry = false;
                    } else {
                        indices[k] = 0;
                    }
                }
            }
            if (carry) break;
        }
        return result;
    }

