    pub fn mean(self: *const Tensor, allocator: Allocator, axis: usize) !Tensor {
        if (self.shape[axis] == 0) return error.EmptyAxis;
        var s = try self.sum(allocator, axis);
        defer s.deinit();
        const div = @as(f32, @floatFromInt(self.shape[axis]));
        s.divScalar(div);
        return try s.copy(allocator);
    }

    pub fn variance(self: *const Tensor, allocator: Allocator, axis: usize) !Tensor {
        if (self.shape[axis] <= 1) return error.InvalidForVariance;
        var m = try self.mean(allocator, axis);
        defer m.deinit();
        var diff = try self.copy(allocator);
        defer diff.deinit();
        var b_shape = try allocator.dupe(usize, self.shape);
        defer allocator.free(b_shape);
        b_shape[axis] = 1;
        var b_mean = try m.broadcast(allocator, b_shape);
        defer b_mean.deinit();
        try diff.sub(&b_mean);
        try diff.mul(&diff);
        var v = try diff.sum(allocator, axis);
        defer v.deinit();
        const ddof: f32 = 1.0;
        const n = @as(f32, @floatFromInt(self.shape[axis]));
        v.divScalar(n - ddof);
        return try v.copy(allocator);
    }

    pub fn stddev(self: *const Tensor, allocator: Allocator, axis: usize) !Tensor {
        var v = try self.variance(allocator, axis);
        defer v.deinit();
        v.sqrt();
        return try v.copy(allocator);
    }

