    pub fn broadcast(self: *const Tensor, allocator: Allocator, target_shape: []const usize) !Tensor {
        if (self.ndim != target_shape.len) return error.ShapeMismatch;
        for (0..self.ndim) |i| {
            const s1 = self.shape[i];
            const s2 = target_shape[i];
            if (s1 != s2 and s1 != 1 and s2 != 1) return error.BroadcastIncompatible;
        }
        var new_tensor = try init(allocator, target_shape);
        var indices = try allocator.alloc(usize, self.ndim);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var src_indices = try allocator.alloc(usize, self.ndim);
            defer allocator.free(src_indices);
            for (0..self.ndim) |dim| {
                src_indices[dim] = if (self.shape[dim] == 1) 0 else indices[dim] % self.shape[dim];
            }
            const val = self.get(src_indices);
            new_tensor.set(indices, val);
            var carry = true;
            var j = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                indices[j] += 1;
                if (indices[j] < target_shape[j]) {
                    carry = false;
                } else {
                    indices[j] = 0;
                }
            }
            if (carry) break;
        }
        return new_tensor;
    }

    pub fn reshape(self: *Tensor, new_shape: []const usize) !void {
        var new_size: usize = 1;
        for (new_shape) |s| {
            if (s == 0) return error.InvalidShape;
            new_size *= s;
        }
        if (new_size != self.data.len) return error.InvalidReshape;
        self.allocator.free(self.shape);
        self.shape = try self.allocator.dupe(usize, new_shape);
        self.ndim = new_shape.len;
        var stride: usize = 1;
        var i = self.ndim;
        while (i > 0) {
            i -= 1;
            self.strides[i] = stride;
            stride *= new_shape[i];
        }
    }

    pub fn transpose(self: *const Tensor, allocator: Allocator, axes: []const usize) !Tensor {
        if (axes.len != self.ndim) return error.InvalidAxes;
        var seen = try allocator.alloc(bool, self.ndim);
        defer allocator.free(seen);
        @memset(seen, false);
        for (axes) |ax| {
            if (ax >= self.ndim or seen[ax]) return error.InvalidAxes;
            seen[ax] = true;
        }
        var new_shape = try allocator.alloc(usize, self.ndim);
        defer allocator.free(new_shape);
        for (axes, 0..) |ax, i| {
            new_shape[i] = self.shape[ax];
        }
        var new_tensor = try init(allocator, new_shape);
        var indices = try allocator.alloc(usize, self.ndim);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var src_indices = try allocator.alloc(usize, self.ndim);
            defer allocator.free(src_indices);
            for (axes, 0..) |ax, i| {
                src_indices[ax] = indices[i];
            }
            const val = self.get(src_indices);
            new_tensor.set(indices, val);
            var carry = true;
            var j = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                indices[j] += 1;
                if (indices[j] < new_tensor.shape[j]) {
                    carry = false;
                } else {
                    indices[j] = 0;
                }
            }
            if (carry) break;
        }
        return new_tensor;
    }

    pub fn slice(self: *const Tensor, allocator: Allocator, ranges: []const [2]usize) !Tensor {
        if (ranges.len != self.ndim) return error.InvalidRanges;
        var new_shape = try allocator.alloc(usize, self.ndim);
        defer allocator.free(new_shape);
        for (ranges, 0..) |r, i| {
            if (r[0] > r[1] or r[1] > self.shape[i]) return error.InvalidSlice;
            new_shape[i] = r[1] - r[0];
        }
        var new_tensor = try init(allocator, new_shape);
        var indices = try allocator.alloc(usize, self.ndim);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var src_indices = try allocator.alloc(usize, self.ndim);
            defer allocator.free(src_indices);
            for (ranges, 0..) |r, i| {
                src_indices[i] = indices[i] + r[0];
            }
            const val = self.get(src_indices);
            new_tensor.set(indices, val);
            var carry = true;
            var j = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                indices[j] += 1;
                if (indices[j] < new_shape[j]) {
                    carry = false;
                } else {
                    indices[j] = 0;
                }
            }
            if (carry) break;
        }
        return new_tensor;
    }

    pub fn concatenate(allocator: Allocator, tensors: []const Tensor, axis: usize) !Tensor {
        if (tensors.len == 0) return error.EmptyConcat;
        const ndim = tensors[0].ndim;
        if (axis >= ndim) return error.InvalidAxis;
        const base_shape = tensors[0].shape;
        for (tensors) |ten| {
            if (ten.ndim != ndim) return error.ShapeMismatch;
            for (0..ndim) |i| {
                if (i != axis and ten.shape[i] != base_shape[i]) return error.ShapeMismatch;
            }
        }
        var new_shape = try allocator.dupe(usize, base_shape);
        for (tensors[1..]) |ten| {
            new_shape[axis] += ten.shape[axis];
        }
        var new_tensor = try init(allocator, new_shape);
        allocator.free(new_shape);
        var offset: usize = 0;
        var global_indices = try allocator.alloc(usize, ndim);
        defer allocator.free(global_indices);
        for (tensors) |ten| {
            var local_indices = try allocator.alloc(usize, ndim);
            defer allocator.free(local_indices);
            @memset(local_indices, 0);
            while (true) {
                @memcpy(global_indices[0..ndim], local_indices[0..ndim]);
                global_indices[axis] = offset + local_indices[axis];
                const val = ten.get(local_indices);
                new_tensor.set(global_indices, val);
                var carry = true;
                var k = ndim;
                while (carry and k > 0) {
                    k -= 1;
                    local_indices[k] += 1;
                    if (local_indices[k] < ten.shape[k]) {
                        carry = false;
                    } else {
                        local_indices[k] = 0;
                    }
                }
                if (carry) break;
            }
            offset += ten.shape[axis];
        }
        return new_tensor;
    }

    pub fn stack(allocator: Allocator, tensors: []const Tensor, axis: usize) !Tensor {
        if (tensors.len == 0) return error.EmptyStack;
        const ndim = tensors[0].ndim;
        if (axis > ndim) return error.InvalidAxis;
        for (tensors) |ten| {
            if (ten.ndim != ndim or !mem.eql(usize, ten.shape, tensors[0].shape)) return error.ShapeMismatch;
        }
        var new_shape = try allocator.alloc(usize, ndim + 1);
        var k: usize = 0;
        for (0..ndim + 1) |i| {
            if (i == axis) {
                new_shape[i] = tensors.len;
            } else {
                new_shape[i] = tensors[0].shape[k];
                k += 1;
            }
        }
        var new_tensor = try init(allocator, new_shape);
        allocator.free(new_shape);
        var indices = try allocator.alloc(usize, ndim + 1);
        defer allocator.free(indices);
        @memset(indices, 0);
        var local_indices = try allocator.alloc(usize, ndim);
        defer allocator.free(local_indices);
        while (true) {
            const ten_idx = indices[axis];
            var l: usize = 0;
            for (0..ndim + 1) |g| {
                if (g != axis) {
                    local_indices[l] = indices[g];
                    l += 1;
                }
            }
            const val = tensors[ten_idx].get(local_indices);
            new_tensor.set(indices, val);
            var carry = true;
            var j = ndim + 1;
            while (carry and j > 0) {
                j -= 1;
                indices[j] += 1;
                if (indices[j] < new_tensor.shape[j]) {
                    carry = false;
                } else {
                    indices[j] = 0;
                }
            }
            if (carry) break;
        }
        return new_tensor;
    }

    pub fn tile(self: *const Tensor, allocator: Allocator, reps: []const usize) !Tensor {
        if (reps.len != self.ndim) return error.InvalidReps;
        var new_shape = try allocator.alloc(usize, self.ndim);
        defer allocator.free(new_shape);
        for (0..self.ndim) |i| {
            new_shape[i] = self.shape[i] * reps[i];
        }
        var new_tensor = try init(allocator, new_shape);
        var indices = try allocator.alloc(usize, self.ndim);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var src_indices = try allocator.alloc(usize, self.ndim);
            defer allocator.free(src_indices);
            for (0..self.ndim) |i| {
                src_indices[i] = indices[i] % self.shape[i];
            }
            const val = self.get(src_indices);
            new_tensor.set(indices, val);
            var carry = true;
            var j = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                indices[j] += 1;
                if (indices[j] < new_shape[j]) {
                    carry = false;
                } else {
                    indices[j] = 0;
                }
            }
            if (carry) break;
        }
        return new_tensor;
    }

    pub fn pad(self: *const Tensor, allocator: Allocator, pads: []const [2]usize) !Tensor {
        if (pads.len != self.ndim) return error.InvalidPads;
        var new_shape = try allocator.alloc(usize, self.ndim);
        defer allocator.free(new_shape);
        for (0..self.ndim) |i| {
            new_shape[i] = self.shape[i] + pads[i][0] + pads[i][1];
        }
        var new_tensor = try init(allocator, new_shape);
        new_tensor.fill(0.0);
        var indices = try allocator.alloc(usize, self.ndim);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var src_indices = try allocator.alloc(usize, self.ndim);
            defer allocator.free(src_indices);
            var is_padding = false;
            for (0..self.ndim) |i| {
                if (indices[i] < pads[i][0] or indices[i] >= pads[i][0] + self.shape[i]) {
                    is_padding = true;
                    src_indices[i] = 0;
                } else {
                    src_indices[i] = indices[i] - pads[i][0];
                }
            }
            if (!is_padding) {
                const val = self.get(src_indices);
                new_tensor.set(indices, val);
            }
            var carry = true;
            var j = self.ndim;
            while (carry and j > 0) {
                j -= 1;
                indices[j] += 1;
                if (indices[j] < new_shape[j]) {
                    carry = false;
                } else {
