            out.data[out_idx] = acc;
            var carry = true;
            k = self.ndim;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    base_idx[k] += 1;
                    if (base_idx[k] < self.shape[k]) {
                        carry = false;
                    } else {
                        base_idx[k] = 0;
                    }
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn mean(self: *const Tensor, allocator: Allocator, axis: usize) TensorError!Tensor {
        if (axis >= self.ndim) return TensorError.InvalidAxis;
        if (self.shape[axis] == 0) return TensorError.EmptyAxis;
        var s = try self.sum(allocator, axis);
        defer s.deinit();
        const divv = @as(f32, @floatFromInt(self.shape[axis]));
        s.divScalar(divv);
        return try s.copy(allocator);
    }

    pub fn variance(self: *const Tensor, allocator: Allocator, axis: usize) TensorError!Tensor {
        if (axis >= self.ndim) return TensorError.InvalidAxis;
        if (self.shape[axis] <= 1) return TensorError.InvalidForVariance;
        var m = try self.mean(allocator, axis);
        defer m.deinit();
        var diff = try self.copy(allocator);
        defer diff.deinit();
        var b_shape = try allocator.dupe(usize, self.shape);
        defer allocator.free(b_shape);
        b_shape[axis] = 1;
        var b_mean = try m.broadcast(allocator, b_shape);
        defer b_mean.deinit();
        try diff.sub(&b_mean);
        var sq = try diff.copy(allocator);
        defer sq.deinit();
        try sq.mul(&sq);
        var v = try sq.sum(allocator, axis);
        defer v.deinit();
        const n = @as(f32, @floatFromInt(self.shape[axis]));
        v.divScalar(n - 1.0);
        return try v.copy(allocator);
    }

    pub fn stddev(self: *const Tensor, allocator: Allocator, axis: usize) TensorError!Tensor {
        var v = try self.variance(allocator, axis);
        defer v.deinit();
        v.sqrt();
        return try v.copy(allocator);
    }

    pub fn argmax(self: *const Tensor, allocator: Allocator, axis: usize) TensorError!Tensor {
        if (axis >= self.ndim) return TensorError.InvalidAxis;
        if (self.shape[axis] == 0) return TensorError.EmptyAxis;
        var new_shape = try allocator.dupe(usize, self.shape);
        defer allocator.free(new_shape);
        new_shape[axis] = 1;
        var out = try init(allocator, new_shape);
        var base_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(base_idx);
        for (base_idx) |*v| v.* = 0;
        while (true) {
            var off: usize = 0;
            var k: usize = 0;
            while (k < self.ndim) : (k += 1) if (k != axis) off += base_idx[k] * self.strides[k];
            var best: f32 = -math.inf(f32);
            var best_i: usize = 0;
            var j: usize = 0;
            while (j < self.shape[axis]) : (j += 1) {
                const idx = off + j * self.strides[axis];
                const val = self.data[idx];
                if (val > best) {
                    best = val;
                    best_i = j;
                }
            }
            var out_idx: usize = 0;
            k = 0;
            while (k < self.ndim) : (k += 1) if (k != axis) out_idx += base_idx[k] * out.strides[k];
            out.data[out_idx] = @as(f32, @floatFromInt(best_i));
            var carry = true;
            k = self.ndim;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    base_idx[k] += 1;
                    if (base_idx[k] < self.shape[k]) {
                        carry = false;
                    } else {
                        base_idx[k] = 0;
                    }
                }
            }
            if (carry) break;
        }
        return out;
    }

