    pub fn sort(self: *const Tensor, allocator: Allocator, axis: usize, descending: bool) TensorError!Tensor {
        if (axis >= self.ndim) return TensorError.InvalidAxis;
        var out = try self.copy(allocator);
        const dim = self.shape[axis];
        if (dim == 0) return out;
        var base_idx = try allocator.alloc(usize, self.ndim);
        defer allocator.free(base_idx);
        for (base_idx) |*v| v.* = 0;
        var temp = try allocator.alloc(f32, dim);
        defer allocator.free(temp);
        while (true) {
            var off: usize = 0;
            var k: usize = 0;
            while (k < self.ndim) : (k += 1) if (k != axis) off += base_idx[k] * self.strides[k];
            var j: usize = 0;
            while (j < dim) : (j += 1) temp[j] = out.data[off + j * self.strides[axis]];
            if (descending) {
                std.sort.sort(f32, temp, {}, std.sort.desc(f32));
            } else {
                std.sort.sort(f32, temp, {}, std.sort.asc(f32));
            }
            j = 0;
            while (j < dim) : (j += 1) out.data[off + j * self.strides[axis]] = temp[j];
            var carry = true;
            k = self.ndim;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    base_idx[k] += 1;
                    if (base_idx[k] < self.shape[k]) {
                        carry = false;
                    } else {
                        base_idx[k] = 0;
                    }
                }
            }
            if (carry) break;
        }
        return out;
    }

    pub fn unique(self: *const Tensor, allocator: Allocator) TensorError!Tensor {
        var sorted = try allocator.alloc(f32, self.data.len);
        defer allocator.free(sorted);
        @memcpy(sorted, self.data);
        std.sort.sort(f32, sorted, {}, std.sort.asc(f32));
        var unique_count: usize = 0;
        var i: usize = 0;
        while (i < sorted.len) : (i += 1) {
            if (unique_count == 0 or math.fabs(sorted[unique_count - 1] - sorted[i]) > 1e-6) {
                sorted[unique_count] = sorted[i];
                unique_count += 1;
            }
        }
        var out = try init(allocator, &.{ unique_count });
        @memcpy(out.data, sorted[0..unique_count]);
        return out;
    }

    pub fn isClose(self: *const Tensor, other: *const Tensor, rtol: f32, atol: f32) bool {
        if (self.ndim != other.ndim or !mem.eql(usize, self.shape, other.shape)) return false;
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) {
            const a = self.data[i];
            const b = other.data[i];
            const diff = math.fabs(a - b);
            if (!(diff <= (atol + rtol * math.fabs(b)))) return false;
        }
        return true;
    }

    pub fn randomUniform(self: *Tensor, min: f32, max: f32, seed: u64) void {
        var prng = std.rand.DefaultPrng.init(seed);
        var rnd = prng.random();
        const range = max - min;
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) {
            self.data[i] = rnd.float(f32) * range + min;
        }
    }

    pub fn randomNormal(self: *Tensor, mean: f32, stddevv: f32, seed: u64) void {
        var prng = std.rand.DefaultPrng.init(seed);
        var rnd = prng.random();
        var i: usize = 0;
        while (i < self.data.len) : (i += 2) {
            var u1 = rnd.float(f32);
            if (u1 <= 0.0) u1 = 1e-7;
            const u2 = rnd.float(f32);
            const r = math.sqrt(-2.0 * math.log(u1));
            const theta = 2.0 * math.pi * u2;
            const z0 = r * math.cos(theta);
            self.data[i] = mean + stddevv * z0;
            if (i + 1 < self.data.len) {
                const z1 = r * math.sin(theta);
                self.data[i + 1] = mean + stddevv * z1;
            }
        }
    }

    pub fn arange(allocator: Allocator, start: f32, end: f32, step: f32) TensorError!Tensor {
        if (step == 0.0) return TensorError.ZeroStep;
        var len: usize = 0;
        if (step > 0.0) {
            var x = start;
            while (x < end) : (x += step) len += 1;
        } else {
            var x = start;
            while (x > end) : (x += step) len += 1;
        }
        var out = try init(allocator, &.{ len });
        var x = start;
        var i: usize = 0;
        if (step > 0.0) {
            while (i < len) : (i += 1) {
                out.data[i] = x;
                x += step;
            }
        } else {
            while (i < len) : (i += 1) {
                out.data[i] = x;
                x += step;
            }
        }
        return out;
    }
};
